    <div style="background:#3e2723;padding:20px;border-radius:12px;border:1px solid #81c784;margin-bottom:20px;">
    <h3 style="color:#e8f5e9;margin-top:0;">🧠 Lesson Summary</h3>
    <p>Soil erosion is the removal of topsoil by water or wind. Signs include exposed roots, rills, gullies, muddy run-off and stones on the surface. Water erosion develops from splash to sheet, rill and gully. Causes include bare soil, slopes, overgrazing, poor ploughing and deforestation; effects include lower yields, gullies, siltation and floods.</p>
    <h4 style="color:#e8f5e9;margin:16px 0 6px 0;">🗒️ Revision notes</h4>
    <ul style="margin:6px 0;padding-left:22px;">
    <li>Erosion.</li>
    <li>Signs.</li>
    <li>Types.</li>
    <li>Causes and effects.</li>
    </ul>
    </div>
