    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #33415c;border-left:4px solid #22d3ee;">
    <h3 style="color:#c8e6c9;margin-top:0;">🔭 Business Background</h3>
    <p><strong>Tanks:</strong> plastic tanks are light and easy to install; masonry (stone or brick) and ferro-cement tanks are strong and can be very large. <strong>Underground tanks</strong> keep water cool and save space but need pumping and careful sealing. <strong>Shallow water pans</strong> are dug pits that collect surface run-off; they are cheap but lose water to evaporation and seepage, so they may be lined and shaded. <strong>Ponds and small dams</strong> store larger volumes for livestock and irrigation and must be fenced for safety. <strong>Suitable containers</strong> for household use include clean jerricans, drums, buckets with lids and clay pots; they must be food-grade, clean and covered. Containers once used for chemicals must never be used.</p>
    </div>
